dev-browser --headless --timeout 25 <<'EOF'
const page = await browser.getPage('crash-benchmark');
const errors=[];
page.on('console', msg => { if(msg.type()==='error') errors.push(msg.text()); });
page.on('pageerror', err => errors.push(String(err)));
await page.setViewportSize({width: 1440, height: 900});
await page.goto('file:///Users/melvynx/Developer/experiments/benchmarks/car-crash/2026-07-13-ccx-gpt-5-6-sol-2/index.html');
await page.waitForTimeout(500);
const initial = await page.evaluate(() => ({
  title: document.title,
  heading: document.querySelector('.brand-name')?.textContent,
  speedSetting: document.querySelector('#carSpeed')?.value,
  columns: document.querySelector('#wallColumns')?.value,
  rows: document.querySelector('#wallRows')?.value,
  depth: document.querySelector('#wallDepth')?.value,
  mass: document.querySelector('#brickMass')?.value,
  canvas: [document.querySelector('canvas')?.width, document.querySelector('canvas')?.height],
  telemetry: document.querySelector('#movingReadout')?.textContent
}));
await page.getByRole('button',{name:/Test/}).click();
await page.waitForTimeout(1700);
const during = await page.evaluate(() => ({
  state: document.querySelector('#stateText')?.textContent,
  speed: document.querySelector('#speedReadout')?.textContent,
  elapsed: document.querySelector('#timeReadout')?.textContent,
  moving: document.querySelector('#movingReadout')?.textContent,
  impactVisible: document.querySelector('#impactCard')?.classList.contains('show')
}));
await page.getByRole('button',{name:'Reset'}).click();
await page.waitForTimeout(100);
const reset = await page.evaluate(() => ({
  state: document.querySelector('#stateText')?.textContent,
  speed: document.querySelector('#speedReadout')?.textContent,
  elapsed: document.querySelector('#timeReadout')?.textContent,
  moving: document.querySelector('#movingReadout')?.textContent
}));
const screenshot=await saveScreenshot(await page.screenshot(), 'car-crash-verified.png');
console.log(JSON.stringify({initial,during,reset,errors,screenshot},null,2));
EOF

